#include "project_delete_gate.h"
#include <string.h>
#include "pattern_overlap.h"
static int nonzero(const uint8_t *p,unsigned n){unsigned i;uint8_t x=0;for(i=0;i<n;i++)x|=p[i];return x!=0;}
static int valid(const pdg_review *r){unsigned i;if(!r||!nonzero(r->nonce,PDG_NONCE)||r->slot>=12u||r->kind>PDG_RAW)return 0;if(r->kind==PDG_UNAVAILABLE){for(i=0;i<PDG_NAME;i++)if(r->name[i])return 0;return 1;}for(i=0;i<PDG_NAME&&r->name[i];i++)if(r->name[i]<32u||r->name[i]>126u)return 0;if(!i||i==PDG_NAME)return 0;for(;i<PDG_NAME;i++)if(r->name[i])return 0;return 1;}
static int same(const pdg_review *a,const pdg_review *b){return a->slot==b->slot&&a->kind==b->kind&&!memcmp(a->nonce,b->nonce,PDG_NONCE)&&!memcmp(a->digest,b->digest,PDG_DIGEST)&&!memcmp(a->name,b->name,PDG_NAME);}
int pdg_prepare(pdg_gate *g,const pdg_review *r,uint32_t now){pdg_review copy;if(!g||!valid(r)||g->state>PDG_CANCELED||g->state==PDG_RUNNING)return 0;if(g->state==PDG_ARMED&&(uint32_t)(now-g->reviewed_at)>=PDG_TIMEOUT_MS)g->state=PDG_CANCELED;if(g->state==PDG_ARMED)return 0;copy=*r;if((g->state==PDG_DONE||g->state==PDG_CANCELED)&&!memcmp(g->review.nonce,copy.nonce,PDG_NONCE))return 0;g->review=copy;g->reviewed_at=now;g->result=0;g->state=PDG_ARMED;return 1;}
int pdg_cancel(pdg_gate *g,const uint8_t nonce[PDG_NONCE]){if(!g||!nonce||g->state!=PDG_ARMED||memcmp(g->review.nonce,nonce,PDG_NONCE))return 0;g->state=PDG_CANCELED;g->result=0;return 1;}
int pdg_commit(pdg_gate *g,const pdg_review *r,uint32_t now,int (*perform)(void *,const pdg_review *),void *ctx,int *result){pdg_review copy;int value;if(!g||!valid(r)||!perform||!result||fm1_mem_overlap(result,sizeof *result,g,sizeof *g)||!same(&g->review,r))return 0;if(g->state==PDG_DONE){*result=g->result;return 1;}if(g->state!=PDG_ARMED)return 0;if((uint32_t)(now-g->reviewed_at)>=PDG_TIMEOUT_MS){g->state=PDG_CANCELED;return 0;}copy=g->review;g->state=PDG_RUNNING;value=perform(ctx,&copy);g->result=value;g->state=PDG_DONE;*result=value;return 1;}
